/* From Uiverse.io by AhSiber - Tags: simple, minimalist, button */
.__UIV_SCOPE__ button {
 border: 1px solid seagreen;
 border-radius: 5px;
 background: rgb(255, 255, 255);
 color: seagreen;
 font-style: italic;
 padding: 10px;
 padding-right: 14px;
 padding-left: 12px;
 font-size: 17px;
}

.__UIV_SCOPE__ button:hover {
 background-color: seagreen;
 color: white;
 border: 1px solid  seagreen;
}
